from __future__ import annotations

import base64
import gzip
import subprocess
from pathlib import Path

PATCH = gzip.decompress(base64.b64decode(""))


def run(root: Path, *args: str, input_bytes: bytes | None = None) -> None:
    result = subprocess.run(
        args,
        cwd=root,
        input=input_bytes,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        check=False,
    )
    if result.returncode != 0:
        if result.stdout:
            print(result.stdout.decode("utf-8", "replace"), end="")
        if result.stderr:
            print(result.stderr.decode("utf-8", "replace"), end="")
        raise SystemExit(result.returncode)


def main() -> int:
    root = Path(__file__).resolve().parents[1]
    if not (root / "Cargo.toml").is_file():
        raise SystemExit("patch utility must run from the FrankenManim source tree")
    run(root, "git", "apply", "--check", "--whitespace=error-all", "-", input_bytes=PATCH)
    run(root, "git", "apply", "--whitespace=error-all", "-", input_bytes=PATCH)
    print("applied Animation composition semantic transaction")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
